// =====================================================
// NUT 2: KIEM TRA VA XAC THUC DU LIEU DAU VAO
// =====================================================
const body = $input.first().json.body || {};

const VALID_STATUSES = ['TODO', 'IN_PROGRESS', 'IN_REVIEW', 'DONE', 'BLOCKED'];

// Kiem tra cac truong bat buoc
const missingFields = [];
if (!body.task_id)    missingFields.push('task_id');
if (!body.new_status) missingFields.push('new_status');
if (!body.old_status) missingFields.push('old_status');

// Kiem tra gia tri status hop le
const invalidStatus = (body.new_status && !VALID_STATUSES.includes(body.new_status))
  ? body.new_status : null;

// Kiem tra xem 2 status co giong nhau khong
const isSameStatus = !!(body.old_status && body.new_status && body.old_status === body.new_status);

// Kiem tra dinh dang UUID cua task_id
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const isValidUUID = body.task_id ? uuidRegex.test(body.task_id) : false;

return [{
  json: {
    is_valid: missingFields.length === 0 && !invalidStatus && !isSameStatus && isValidUUID,
    missing_fields: missingFields,
    invalid_status: invalidStatus,
    same_status: isSameStatus,
    invalid_uuid: body.task_id && !isValidUUID,
    body: body
  }
}];

