// =====================================================
// NUT 10: TINH LEAD TIME VA PHAT HIEN BOTTLENECK
// =====================================================
const webhookBody = $('Code - Validate Input').first().json.body;
const taskData = $input.first().json;

const newStatus  = webhookBody.new_status;
const oldStatus  = webhookBody.old_status;

// --- Tinh Lead Time (chi khi DONE) ---
let lead_time_hours = null;
let is_overdue = false;

if (newStatus === 'DONE' && taskData.created_at) {
  const createdAt = new Date(taskData.created_at);
  const now       = new Date();
  lead_time_hours = Math.round(((now - createdAt) / (1000 * 60 * 60)) * 100) / 100;

  if (taskData.due_date) {
    is_overdue = now > new Date(taskData.due_date);
  }
}

// --- Phat hien Bottleneck ---
const is_bottleneck = newStatus === 'BLOCKED';

// --- Tao thong diep phu hop ---
let message;
if (newStatus === 'DONE') {
  message = is_overdue
    ? 'Task hoan thanh MUON! Lead time: ' + lead_time_hours + ' gio'
    : 'Task hoan thanh dung han! Lead time: ' + lead_time_hours + ' gio';
} else if (is_bottleneck) {
  message = 'CANH BAO: Task bi BLOCKED - can kiem tra nguon luc!';
} else {
  message = 'Trang thai thay doi: ' + oldStatus + ' -> ' + newStatus;
}

return [{
  json: {
    task_id:          webhookBody.task_id,
    task_title:       taskData.title || webhookBody.task_title || null,
    project_id:       webhookBody.project_id || null,
    old_status:       oldStatus,
    new_status:       newStatus,
    changed_by:       webhookBody.changed_by || null,
    lead_time_hours:  lead_time_hours,
    is_bottleneck:    is_bottleneck,
    is_overdue:       is_overdue,
    story_points:     taskData.story_points || null,
    timestamp:        webhookBody.timestamp || new Date().toISOString(),
    message:          message
  }
}];

// =====================================================
// NUT 14: TOM TAT KHI TASK HOAN THANH (DONE)
// =====================================================
const data = $('Code - Calculate Lead Time').first().json;

const efficiency = data.lead_time_hours && data.story_points
  ? Math.round((data.story_points / data.lead_time_hours) * 100) / 100
  : null;

const badge = data.is_overdue ? 'HOAN THANH MUON' : 'HOAN THANH DUNG HAN';

return [{
  json: {
    event:            'TASK_COMPLETED',
    badge:            badge,
    task_id:          data.task_id,
    task_title:       data.task_title,
    lead_time_hours:  data.lead_time_hours,
    story_points:     data.story_points,
    efficiency_score: efficiency,
    is_overdue:       data.is_overdue,
    summary_message:  badge + ' | Task: ' + (data.task_title || data.task_id) + ' | Lead time: ' + data.lead_time_hours + 'h',
    processed_at:     new Date().toISOString()
  }
}];
